// spec: specs/buyer-request-guest.md (2.1–2.3) · кейсы: .qa/tests/buyer-request-guest/BUYREQ-GUEST-03.md, -04.md
// seed: tests/seed.spec.ts (гость) · ПРОД, без записи: POST rest/v1/demanded_business получает подменённый ответ
// (в базу ничего не пишется), прочие не-GET обрываются. Реальная публикация гостем — только вручную (создаёт данные).
import { test, expect, Page } from '@playwright/test';
import { ERROR, INPUT, LOAD, SUCCESS, fillRequest, interceptWrites, openAsGuest, submitButton } from './buyer-request-guest.helpers';

test.use({ storageState: { cookies: [], origins: [] }, serviceWorkers: 'block' });

async function guestSubmitOk(page: Page) {
  const ctl = await interceptWrites(page, 'ok');
  await openAsGuest(page);
  await fillRequest(page);
  await submitButton(page).click();
  await expect(page.getByText(SUCCESS), `«${SUCCESS}»`).toBeVisible(LOAD);
  await expect(page.getByText(ERROR), 'нет «שגיאה בפרסום הבקשה»').toHaveCount(0);

  expect(ctl.inserts.length, 'ровно один POST demanded_business (подменён)').toBe(1);
  const body = ctl.inserts[0];
  expect(body).toMatchObject({
    title: INPUT.title,
    city: INPUT.city,
    contact_name: INPUT.contact_name,
    contact_phone: INPUT.contact_phone,
    status: 'פעיל',
  });
  // Комментарий программиста: гость добавляет заявку «בלי מייל של בעלים».
  expect(body.contact_email ?? null, 'contact_email = null').toBeNull();
  expect(body.created_by ?? null, 'created_by = null').toBeNull();
  expect(body.user_email ?? null, 'user_email = null').toBeNull();

  await expect(page, 'переход в «קונים מחפשים»').toHaveURL(/\/buyerlistings/, LOAD);
  expect(ctl.unexpected, 'других запросов на запись нет').toEqual([]);
}

test.describe('מה אני מחפש לקנות? — гость публикует заявку (ответ сервера подменён)', () => {
  test('Гость: заполненная форма → запрос без e-mail владельца, «הבקשה פורסמה בהצלחה!», переход на /buyerlistings #da55b1 @desktop @prod-safe', async ({ page }) => {
    await guestSubmitOk(page);
  });

  test('Телефон: гость публикует заявку — успех без ошибки, переход на /buyerlistings #da55b1 @android @prod-safe', async ({ page }) => {
    await guestSubmitOk(page);
  });

  test('Гость: сервер отказал (403) → «שגיאה בפרסום הבקשה, אנא נסה שנית.», форма не сброшена #da55b1 @desktop @prod-safe', async ({ page }) => {
    const ctl = await interceptWrites(page, 403);
    await openAsGuest(page);
    await fillRequest(page);
    await submitButton(page).click();
    await expect(page.getByText(ERROR), `«${ERROR}»`).toBeVisible(LOAD);
    await expect(page.getByText(SUCCESS)).toHaveCount(0);
    await expect(page).toHaveURL(/\/postbuyerrequest/);
    await expect(page.locator('#title'), 'введённая «כותרת הבקשה» на месте').toHaveValue(INPUT.title);
    await expect(submitButton(page), '«פרסם בקשה» снова доступна').toBeEnabled();
    expect(ctl.inserts.length, 'один POST demanded_business (подменён 403)').toBe(1);
    expect(ctl.unexpected, 'других запросов на запись нет').toEqual([]);
  });
});
